const SECTIONS = [[0,"prelude"],[64,"canon"],[104,"exposition"],[132,"episode"],[140,"middle entry"],[148,"episode II"],[156,"middle entry II"],[164,"episode III"],[176,"stretto"],[188,"coda"]]
const END = 196
const FUGUE = 104 // the fugue begins (before it: the canon)
const TUTTI = 176 // the stretto or the last entry, and the coda: everyone
const C4 = 440 * 2 ** (-9 / 12) // 261.63 Hz, exact equal temperament
const PHASES = { prelude: [0, 64], canon: [64, FUGUE], fugue: [FUGUE, TUTTI], tutti: [TUTTI, END] }
// the note of a voice at x in the given phases (moved by dn semitones: a 4′ or a 16′ doubling) → { n, d, τ, u, at } or null
const playing = (list, x, phases, dn = 0) => {
  if (!phases.some(p => x >= PHASES[p][0] && x < PHASES[p][1])) return null
  const m = notesAt(list, x)
  return m && (dn ? { ...m, n: m.n + dn } : m)
}

